// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract MyToken {
    // 代币基本信息
    string public name;  // 中文名
    string public symbol;  // 英文名
    uint8 public decimals; // 小数位
    uint256 public totalSupply;  // 代币数量

    // 状态变量
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    // 所有者
    address public  owner;

    // 事件 用于记录log indexed用于创建索引进行搜索
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approve(address indexed owner, address indexed spender, uint256 value);

    // 修饰符
    modifier onlyOwner(){
        require(msg.sender == owner, "Only owner can call this");
        _;
    }

    // 构造函数
    constructor(
        string memory _name,
        string memory _symbol,
        uint8 _decimals,
        uint256 _initialSupply
    ){
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        totalSupply = _initialSupply * 10 ** _decimals;
        owner = msg.sender;
        balanceOf[msg.sender] = totalSupply;
        emit Transfer(address(0), msg.sender, totalSupply);
    }

    // 转账函数
    function transfer(address to, uint256 amount) public returns (bool) {
        require(to != address(0), "Can not transfer to zero address");
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");

        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;

        emit Transfer(msg.sender, to, amount);

        return true;
    }

    // 授权函数
    function approve(address spender, uint256 amount) public returns (bool){
        require(spender != address(0), "Can not approve zero address");

        allowance[msg.sender][spender] = amount;

        emit Approve(msg.sender, spender, amount);

        return true;
    }

    // 授权转账函数
    function transferFrom(address from, address to, uint256 amount) public returns (bool){
        require(from != address(0), "Can not transfer from zero address");
        require(to != address(0), "Can not transfer to zero address");
        require(balanceOf[from] >= amount, "Insufficient balance");
        require(allowance[from][msg.sender] >= amount, "Insufficient allowance");

        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;

        emit Transfer(from, to, amount);

        return true;
    }

    // 铸造函数 （可选，需要onlyOwner修饰符）
    function mint(address to, uint256 amount) public onlyOwner {
        require(to != address(0), "Can not mint to zero address");

        totalSupply += amount;
        balanceOf[to] += amount;

        emit Transfer(address(0), to, amount);
    }

    // 销毁函数 （可选）
    function burn(uint256 amount) public {
        require(balanceOf[msg.sender] > amount, "Insufficient balance to burn");

        totalSupply -= amount;
        balanceOf[msg.sender] -= amount;

        emit Transfer(msg.sender, address(0), amount);
    }
}

contracts/lesson6_1/MyConcreteToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// 接口：定了代币合约必须实现的功能
interface IBasicToken {
    function getName() external view returns (string memory);

    function getSymbol() external view returns (string memory);

    function getTotalSupply() external view returns (uint256);

    function getBalance(address account) external view returns (uint256);

    function transfer(address recipient, uint256 amount) external returns (bool);
}

// 抽象合约：实现了部分接口功能，但仍有抽象函数
abstract contract AbstractToken is IBasicToken {
    string public  name;
    string public  symbol;
    uint256 public  totalSupply;
    mapping(address => uint256) private _balances;

    constructor(string memory _name, string memory _symbol, uint256 _initialSupply) {
        name = _name;
        symbol = _symbol;
        totalSupply = _initialSupply;
        _balances[msg.sender] = _initialSupply; // 将初始供应量分配给部署者
    }

    // 实现了接口中的 getBalance 函数
    function getBalance(address account) public view override returns (uint256) {
        return _balances[account];
    }

    // 抽象函数：transfer，必须由继承者实现
    function transfer(address recipient, uint256 amount) public virtual override returns (bool);

    // 辅助函数，供子合约使用
    function _transfer(address sender, address recipient, uint256 amount) internal virtual {
        require(sender != address(0), "Transfer from zero address");
        require(recipient != address(0), "Transfer to zero address");
        require(_balances[sender] >= amount, "Insufficient balance");

        _balances[sender] -= amount;
        _balances[recipient] += amount;
    }

    // 实现了接口中的 getName 和 getSymbol
    function getName() public view override returns (string memory) {
        return name;
    }

    function getSymbol() public view override returns (string memory) {
        return symbol;
    }

    function getTotalSupply() public view override returns (uint256) {
        return totalSupply;
    }
}

// 具体合约：继承抽象合约并实现所有抽象函数
contract MyConcreteToken is AbstractToken("MyToken", "MTK", 1000000) {
    constructor(){} // 继承了父合约的构造函数，并传递了参数

    // 实现抽象合约中的transfer函数
    function transfer(address recipient, uint256 amount) public override returns (bool){
        _transfer(msg.sender, recipient, amount); // 调用抽象合约中的辅助函数
        return true;
    }
}
